def get_3x3_pattern(input_grid, r, c):
    """Get 3x3 pattern around (r,c) - true where grid[r][c]==8"""
    pattern = []
    for dr in range(-1, 2):
        row = []
        for dc in range(-1, 2):
            nr, nc = r+dr, c+dc
            if 0 <= nr < 7 and 0 <= nc < 7:
                row.append(1 if input_grid[nr][nc] == 8 else 0)
            else:
                row.append(-1)  # out of bounds
        pattern.append(row)
    return tuple(tuple(row) for row in pattern)

