def orientation(cells):
    """Return orientation descriptor for 3-cell L"""
    rows = {c for r,c in cells}
    cols = {r for r,c in cells}
    rmin, rmax = min(rows), max(rows)
    cmin, cmax = min(cols), max(cols)

    ar = rmax - rmin  # row span
    ac = cmax - cmin  # col span

    # Return shape: (min_r, min_c) is corner
    return (rmin, cmin, ar, ac)

